using UnityEngine;namespace FallenForest.UI{public sealed class MenuCameraDrift:MonoBehaviour{[SerializeField]private float yawAmplitude=1.15f,pitchAmplitude=.42f,speed=.065f,positionAmplitude=.035f;private Quaternion baseRotation;private Vector3 basePosition;private float seed;private void Awake(){baseRotation=transform.localRotation;basePosition=transform.localPosition;seed=Random.value*90f;}private void LateUpdate(){float t=Time.unscaledTime*speed+seed;transform.localRotation=baseRotation*Quaternion.Euler(Mathf.Sin(t*.71f+1.3f)*pitchAmplitude,Mathf.Sin(t*1.07f)*yawAmplitude,0);transform.localPosition=basePosition+new Vector3(Mathf.Sin(t*.63f),Mathf.Sin(t*.81f+2f),0)*positionAmplitude;}}}
